@import '../../style/workFlow.scss';
::v-deep .workFlow-dialog {
  height: 521px;
  .el-dialog__body {
    padding: 15px 16px 0;
    overflow-x: hidden;
  }
  .el-dialog__body{
    position: relative;
    .commentTextarea .el-textarea__inner{
      height: 240px;
      padding: 10px 15px 40px 15px;
    }
    .el-radio__label{
      line-height: 25px !important;
    }
    .anyRejectDiv{
      display: flex;
      align-items: center;
      justify-content: flex-start;
      width: 100%;
      min-height: 40px;
      border: 1px solid #E7E7E7;
      margin-top: 6px;
      padding: 0 0 0 20px;
      box-sizing: border-box;
      .el-checkbox-group {
        display: flex;
        line-height: 40px;
        flex-wrap: wrap;
        align-items: center;
        >label {
          margin-right: 25px !important;
          display: flex;
          align-items: center;
          min-height: 40px;
        }
        .el-checkbox {
          line-height: 40px;
        }
        .el-checkbox__label {
          display: inline-block;
          word-break: break-word;
          width: auto;
          white-space: pre-wrap;
        }
      }
    }
  }
  .selectType{
    margin-top: 18px;
    width: 100%;
    overflow: hidden;
    display: flex;
    >span {
      width: 70px;
    }
    >div {
      width: calc(100% - 95px);
      display: flex;
      flex-direction: column;
      margin-left: 25px;
      margin-bottom: 0;
      >.el-radio:not(:nth-child(3)) {
        margin-bottom: 12px;
      }
    }
  }
  .text-box {
    position: relative;
    .bottom-info {
      position: absolute;
      background: #fff;
      width: calc(100% - 2px);
      height: 40px;
      padding: 0 14px;
      box-sizing: border-box;
      display: flex;
      align-items: center;
      justify-content: space-between;
      left: 1px;
      bottom: 1px;
      border-radius: 4px;
    }
  }
  .total-text{
    color:#999999;
  }
  .quick-comments{
    .quick-bottom{
      display: flex;
      color: #4A4C66;
      .quick-bottom1{
        width: 12px;
        height: 13px;
        margin-right: 6px;
        background-image: url('../../../assets/workflow/quick-comments.svg');
        background-size: 12px 13px;
      }
    }
    .quick-bottom:hover{
      color:#0D8EFF;
    }
    .quick-bottom:hover .quick-bottom1{
      background-image: url('../../../assets/workflow/quick-comments1.svg');
    }
  }
}
::v-deep .zidingyi{
  height: 266px;
  .el-dialog__title{
    font-size: 14px;
  }
  .zdy-top{
    display: flex;
    justify-content: space-between;
    margin-bottom: 15px;
  }
  .delete{
    display: none;
  }
  .zdy-bottom{

    .zdy-bottom-top{
      display: flex;
      justify-content: space-between;
    }
  }
  .zdy-bottom:hover{
    background: #E9F4FE;
    .delete{
      display: block;
      width: 16px;
      height: 16px;
      background-image: url('../../../assets/workflow/delete.svg');
      margin-top:5px
    }
  }
  .el-dialog__body{
    height: 220px;
    padding: 24px 20px 0;
  }
  .boder{
    padding-top: 3px;
    width: 388px;
    height: 156px;
    border: 1px solid #E7E7E7;
  }
}
